/**
 * Deterministic sample market data for the Trading Lab.
 *
 * IMPORTANT: This is SYNTHETIC sample data generated by a seeded random walk with
 * realistic-looking structure (trend, pullbacks, volatility clustering). It is
 * NOT real market data, NOT live data, and NOT sourced from any exchange feed.
 * The UI labels every chart accordingly. Do not present it as real prices.
 */

export interface Candle {
  time: number; // UTC seconds
  open: number;
  high: number;
  low: number;
  close: number;
  volume: number;
}

export interface SampleInstrument {
  id: string;
  name: string;
  symbol: string;
  description: string;
  basePrice: number;
  volatility: number; // per-bar log-return std dev
  drift: number; // per-bar drift
  ticker: string;
}

