/** Small deterministic PRNG (mulberry32) so charts are identical on every render. */
function mulberry32(seed: number) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function gaussian(rng: () => number) {
  // Box–Muller transform
  let u = 0;
  let v = 0;
  while (u === 0) u = rng();
  while (v === 0) v = rng();
  return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
}

const DAY = 24 * 60 * 60;

/**
 * Builds `count` daily candles ending on a fixed date so the series never
 * silently changes between sessions.
 */
export function buildSeries(instrument: SampleInstrument, count = 500): Candle[] {
  const seed = [...instrument.id].reduce((acc, ch) => acc + ch.charCodeAt(0) * 31, 7);
  const rng = mulberry32(seed);
  const candles: Candle[] = [];

  // Price at the start of the window, back-computed from basePrice.
  let price = instrument.basePrice * 0.72;
  // End date fixed so the sample window never shifts.
  const endTime = Date.UTC(2025, 11, 31);
  let vol = instrument.volatility;

  for (let i = 0; i < count; i++) {
    // Volatility clustering: vol mean-reverts but is shocked occasionally.
    vol = vol * 0.94 + instrument.volatility * 0.06;
    if (rng() < 0.03) vol *= 1.45 + rng() * 0.9;

    // Slow regime drift so the series has visible trends and ranges.
    const regime = Math.sin((i / count) * Math.PI * 4 + seed * 0.01) * instrument.volatility * 0.55;
    const ret = instrument.drift + regime * 0.35 + gaussian(rng) * vol;

    const open = price;
    const close = Math.max(1, open * Math.exp(ret));
    const wickUp = Math.abs(gaussian(rng)) * vol * open * 0.55;
    const wickDown = Math.abs(gaussian(rng)) * vol * open * 0.55;
    const high = Math.max(open, close) + wickUp;
    const low = Math.max(0.5, Math.min(open, close) - wickDown);

    const baseVolume = 900_000 / Math.sqrt(instrument.basePrice) + 120_000;
    const volume = Math.round(
      baseVolume * (0.55 + rng() * 0.9) * (1 + Math.abs(ret) / instrument.volatility * 0.35),
    );

    candles.push({
      time: endTime - (count - 1 - i) * DAY,
      open: round(open),
      high: round(high),
      low: round(low),
      close: round(close),
      volume,
    });

    price = close;
  }

  return candles;
}

function round(n: number) {
  return Math.round(n * 100) / 100;
}

export const seriesCache = new Map<string, Candle[]>();

export function getSeries(instrumentId: string, count = 500): Candle[] {
  const key = `${instrumentId}:${count}`;
  const cached = seriesCache.get(key);
  if (cached) return cached;
  const inst = sampleInstruments.find((i) => i.id === instrumentId) ?? sampleInstruments[0];
  const series = buildSeries(inst, count);
  seriesCache.set(key, series);
  return series;
}

/* ------------------------------------------------------------------ */
/* Aggregation                                                         */
/* ------------------------------------------------------------------ */

export type Aggregation = 1 | 3 | 5 | 10;

export const aggregations: { value: Aggregation; label: string }[] = [
  { value: 1, label: 'Daily' },
  { value: 3, label: '3 Day' },
  { value: 5, label: 'Weekly' },
  { value: 10, label: 'Bi-weekly' },
];

export function aggregate(candles: Candle[], size: Aggregation): Candle[] {
  if (size === 1) return candles;
  const out: Candle[] = [];
  for (let i = 0; i < candles.length; i += size) {
    const chunk = candles.slice(i, i + size);
    if (!chunk.length) continue;
    out.push({
      time: chunk[chunk.length - 1].time,
      open: chunk[0].open,
      high: Math.max(...chunk.map((c) => c.high)),
      low: Math.min(...chunk.map((c) => c.low)),
      close: chunk[chunk.length - 1].close,
      volume: chunk.reduce((s, c) => s + c.volume, 0),
    });
  }
  return out;
}

/* ------------------------------------------------------------------ */
/* Indicators                                                          */
/* ------------------------------------------------------------------ */

export function sma(values: number[], period: number): (number | null)[] {
  const out: (number | null)[] = [];
  let sum = 0;
  for (let i = 0; i < values.length; i++) {
    sum += values[i];
    if (i >= period) sum -= values[i - period];
    out.push(i >= period - 1 ? sum / period : null);
  }
  return out;
}

export function ema(values: number[], period: number): (number | null)[] {
  const k = 2 / (period + 1);
  const out: (number | null)[] = [];
  let prev: number | null = null;
  for (let i = 0; i < values.length; i++) {
    if (i < period - 1) {
      out.push(null);
      continue;
    }
    if (prev === null) {
      const seed = values.slice(0, period).reduce((a, b) => a + b, 0) / period;
      prev = seed;
      out.push(seed);
      continue;
    }
    prev = values[i] * k + prev * (1 - k);
    out.push(prev);
  }
  return out;
}

export function rsi(values: number[], period = 14): (number | null)[] {
  const out: (number | null)[] = [null];
  let avgGain = 0;
  let avgLoss = 0;
  for (let i = 1; i < values.length; i++) {
    const change = values[i] - values[i - 1];
    const gain = Math.max(change, 0);
    const loss = Math.max(-change, 0);
    if (i <= period) {
      avgGain += gain / period;
      avgLoss += loss / period;
      out.push(i === period ? compute(avgGain, avgLoss) : null);
    } else {
      avgGain = (avgGain * (period - 1) + gain) / period;
      avgLoss = (avgLoss * (period - 1) + loss) / period;
      out.push(compute(avgGain, avgLoss));
    }
  }
  return out;
}

function compute(gain: number, loss: number) {
  if (loss === 0) return 100;
  const rs = gain / loss;
  return 100 - 100 / (1 + rs);
}

export function macd(values: number[], fast = 12, slow = 26, signalPeriod = 9) {
  const fastEma = ema(values, fast);
  const slowEma = ema(values, slow);
  const macdLine = values.map((_, i) =>
    fastEma[i] !== null && slowEma[i] !== null ? (fastEma[i] as number) - (slowEma[i] as number) : null,
  );
  const valid = macdLine.filter((v): v is number => v !== null);
  const signalValid = ema(valid, signalPeriod);
  const offset = macdLine.findIndex((v) => v !== null);
  const signal = macdLine.map((_, i) => {
    if (i < offset) return null;
    return signalValid[i - offset] ?? null;
  });
  const histogram = macdLine.map((v, i) =>
    v !== null && signal[i] !== null ? v - (signal[i] as number) : null,
  );
  return { macdLine, signal, histogram };
}

export function bollinger(values: number[], period = 20, mult = 2) {
  const mid = sma(values, period);
  const upper: (number | null)[] = [];
  const lower: (number | null)[] = [];
  for (let i = 0; i < values.length; i++) {
    if (mid[i] === null || i < period - 1) {
      upper.push(null);
      lower.push(null);
      continue;
    }
    const slice = values.slice(i - period + 1, i + 1);
    const mean = mid[i] as number;
    const variance = slice.reduce((s, v) => s + (v - mean) ** 2, 0) / period;
    const sd = Math.sqrt(variance);
    upper.push(mean + mult * sd);
    lower.push(mean - mult * sd);
  }
  return { mid, upper, lower };
}

export function atr(candles: Candle[], period = 14): (number | null)[] {
  const trs: number[] = [];
  for (let i = 0; i < candles.length; i++) {
    if (i === 0) {
      trs.push(candles[i].high - candles[i].low);
      continue;
    }
    const prevClose = candles[i - 1].close;
    trs.push(
      Math.max(
        candles[i].high - candles[i].low,
        Math.abs(candles[i].high - prevClose),
        Math.abs(candles[i].low - prevClose),
      ),
    );
  }
  return sma(trs, period);
}

export function vwapSeries(candles: Candle[], resetEvery = 20): (number | null)[] {
  // Session-style VWAP, resetting periodically — educational approximation.
  const out: (number | null)[] = [];
  let cumPV = 0;
  let cumV = 0;
  candles.forEach((c, i) => {
    if (i % resetEvery === 0) {
      cumPV = 0;
      cumV = 0;
    }
    const typical = (c.high + c.low + c.close) / 3;
    cumPV += typical * c.volume;
    cumV += c.volume;
    out.push(cumV > 0 ? cumPV / cumV : null);
  });
  return out;
}

/* ------------------------------------------------------------------ */
/* Stats helpers                                                       */
/* ------------------------------------------------------------------ */

export function describeSeries(candles: Candle[]) {
  if (!candles.length) return null;
  const first = candles[0];
  const last = candles[candles.length - 1];
  const closes = candles.map((c) => c.close);
  const high = Math.max(...candles.map((c) => c.high));
  const low = Math.min(...candles.map((c) => c.low));
  const change = last.close - first.open;
  const changePct = (change / first.open) * 100;
  const avgVol = candles.reduce((s, c) => s + c.volume, 0) / candles.length;
  return {
    open: first.open,
    close: last.close,
    high,
    low,
    change,
    changePct,
    avgVolume: avgVol,
    bars: candles.length,
    startTime: first.time,
    endTime: last.time,
    closes,
  };
}

